pluginManagement {
    repositories {
        gradlePluginPortal()
        maven("https://repo.papermc.io/repository/maven-public/")
    }
}

rootProject.name = "multipaper"

// MultiPaper-API and MultiPaper-Server are generated by the paperweight patch
// tasks on the server-port branch. Only include projects whose directories
// exist so the master modules can be built standalone.
for (name in listOf("MultiPaper-MasterMessagingProtocol", "MultiPaper-API", "MultiPaper-Server", "MultiPaper-Master")) {
    if (file(name).isDirectory) {
        val projName = name.lowercase()
        include(projName)
        findProject(":$projName")!!.projectDir = file(name)
    }
}
